WITH m AS (SELECT public.read_nba_decision_learning_metrics_v1('2026-11-01T00:00:00Z'::timestamptz) j),
latest AS (SELECT id,kind,slot,captured_at,diagnostics-'discarded' AS diagnostics FROM nba_v2_shadow.cycles ORDER BY id DESC LIMIT 8),
v1 AS (SELECT f.*,o.forecast_id IS NOT NULL AS settled FROM public.nba_decision_shadow_forecasts_v1 f LEFT JOIN public.nba_decision_shadow_outcomes_v1 o USING(forecast_id))
SELECT transaction_timestamp() AS captured_at,
(SELECT jsonb_agg(latest ORDER BY id) FROM latest) cycles,
(SELECT jsonb_build_object('status',j->>'status','frozen',j->'frozen_rows','outcomes',j->'outcomes_rows','last_frozen',j->'last_frozen_at','last_settled',j->'last_settled_at','baseline_groups',jsonb_array_length(j->'baseline'),'challenger_groups',jsonb_array_length(j->'challengers'),'max_independent_games',(SELECT max((x->>'independentGames')::int) FROM jsonb_array_elements(j->'challengers')x),'promotions',j->'promotions_performed','method',j->>'method','period_total_challengers',(SELECT jsonb_agg(x) FROM jsonb_array_elements(j->'challengers')x WHERE x->>'market'='total' AND x->>'period' IN ('q1','q2','q3','q4','h1','h2'))) FROM m) metrics,
(SELECT jsonb_build_object('forecasts',count(*),'unique_games',count(DISTINCT game_id),'settled',count(*) FILTER(WHERE settled),'settled_games',count(DISTINCT game_id) FILTER(WHERE settled),'pending',count(*) FILTER(WHERE NOT settled),'pending_games',count(DISTINCT game_id) FILTER(WHERE NOT settled),'pending_past_24h',count(*) FILTER(WHERE NOT settled AND game_start_at<transaction_timestamp()-interval '24 hours'),'oldest_pending_tip',min(game_start_at) FILTER(WHERE NOT settled)) FROM v1) v1_summary,
(SELECT jsonb_agg(jsonb_build_object('market',market,'period',period,'frozen',n,'unique_games',games,'settled',settled,'pending',pending) ORDER BY market,period) FROM (SELECT market,period,count(*) n,count(DISTINCT game_id) games,count(*) FILTER(WHERE settled) settled,count(*) FILTER(WHERE NOT settled) pending FROM v1 GROUP BY market,period)p) v1_coverage,
jsonb_build_object('forecasts',(SELECT count(*) FROM nba_v2_shadow.forecasts),'unique_games',(SELECT count(DISTINCT game_id) FROM nba_v2_shadow.forecasts),'judgments',(SELECT count(*) FROM nba_v2_shadow.judgments),'unique_settled_forecasts',(SELECT count(DISTINCT forecast_id) FROM nba_v2_shadow.judgments WHERE record?'result'),'settled_games',(SELECT count(DISTINCT f.game_id) FROM nba_v2_shadow.forecasts f JOIN nba_v2_shadow.judgments j ON j.forecast_id=f.id WHERE j.record?'result'),'records_from_natural_cycle4',(SELECT count(*) FROM nba_v2_shadow.forecasts WHERE cycle_id=4),'reports',(SELECT count(*) FROM nba_v2_shadow.reports)) v2_summary;
